// @FIGURE_CODE_BEGIN
var LINES = [
  { name: 'I', m: 3, b: 2, color: '#e87722', seg: [-2.33, 1.0] },
  { name: 'II', m: 0.5, b: 3, color: '#4a9fd8', seg: [-7, 4] },
  { name: 'III', m: 2, b: -3, color: '#1a9e8f', seg: [-1, 4] },
  { name: 'IV', m: -2, b: 3, color: '#1f3a93', seg: [-1, 4] }
];
var selM = 1, selB = 1, selLine = -1;
var chart;

function candPts(m, b) {
  // endpoints where line crosses plot box
  var xs = [];
  [[-7, m * -7 + b], [7, m * 7 + b]].forEach(function (p) { if (p[1] >= -5 && p[1] <= 5) xs.push(p); });
  if (m !== 0) {
    [5, -5].forEach(function (y) {
      var x = (y - b) / m;
      if (x >= -7 && x <= 7) xs.push([x, y]);
    });
  }
  xs.sort(function (a, c) { return a[0] - c[0]; });
  return xs.length >= 2 ? [xs[0], xs[xs.length - 1]] : [];
}

var annotationPlugin = {
  id: 'annot',
  afterDraw: function (c) {
    var ctx = c.ctx, a = c.chartArea;
    function X(x) { return c.scales.x.getPixelForValue(x); }
    function Y(y) { return c.scales.y.getPixelForValue(y); }
    var s = Math.min(a.right - a.left, a.bottom - a.top);
    var fs = Math.max(9, s * 0.028);

    function arrowhead(x1, y1, x2, y2, color) {
      var ang = Math.atan2(y2 - y1, x2 - x1), L = fs * 0.9;
      ctx.strokeStyle = color; ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(x2, y2);
      ctx.lineTo(x2 - L * Math.cos(ang - 0.4), y2 - L * Math.sin(ang - 0.4));
      ctx.lineTo(x2 - L * Math.cos(ang + 0.4), y2 - L * Math.sin(ang + 0.4));
      ctx.closePath(); ctx.fill();
    }

    // axis arrowheads
    arrowhead(X(6.4), Y(0), X(7.15), Y(0), '#333');
    arrowhead(X(0), Y(-4.6), X(0), Y(5.35), '#333');

    // line arrowheads + labels
    LINES.forEach(function (L, i) {
      var p1 = [X(L.seg[0]), Y(L.m * L.seg[0] + L.b)];
      var p2 = [X(L.seg[1]), Y(L.m * L.seg[1] + L.b)];
      arrowhead(p2[0], p2[1], p1[0], p1[1], L.color);
      arrowhead(p1[0], p1[1], p2[0], p2[1], L.color);
      ctx.font = 'italic bold ' + fs + 'px sans-serif';
      ctx.fillStyle = L.color;
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      var labelPt;
      if (L.name === 'IV') labelPt = [p2[0] + fs * 0.4, p2[1] - fs * 0.9];
      else if (L.name === 'I') labelPt = [p2[0] + fs * 0.4, p2[1] + fs * 0.6];
      else if (L.name === 'III') labelPt = [p2[0] + fs * 0.5, p2[1] + fs * 1.3];
      else labelPt = [p2[0] + fs * 0.5, p2[1] - fs * 1.1];
      ctx.fillText(L.name, labelPt[0], labelPt[1]);
    });

    // axis labels
    ctx.fillStyle = '#333'; ctx.font = 'italic ' + fs + 'px serif';
    ctx.textAlign = 'center';
    ctx.fillText('x', X(7.1), Y(0) + fs * 1.1);
    ctx.fillText('y', X(0) - fs * 1.1, Y(5.2));

    // candidate intercept pivot dot
    ctx.fillStyle = '#7b2fbf';
    ctx.beginPath(); ctx.arc(X(0), Y(selB), Math.max(3, fs * 0.35), 0, 7); ctx.fill();

    // rise/run triangle for selected line
    if (selLine >= 0) {
      var L = LINES[selLine];
      var run = 1, rise = L.m;
      var x0 = (L.name === 'IV') ? 0 : 0; // anchor at y-intercept
      var y0 = L.b;
      var px0 = X(x0), py0 = Y(y0), px1 = X(x0 + run), py1 = Y(y0), px2 = X(x0 + run), py2 = Y(y0 + rise);
      ctx.strokeStyle = '#c0392b'; ctx.lineWidth = Math.max(1, fs * 0.12);
      ctx.setLineDash([]);
      ctx.beginPath(); ctx.moveTo(px0, py0); ctx.lineTo(px1, py1); ctx.lineTo(px2, py2); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = '#c0392b'; ctx.font = fs * 0.85 + 'px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      ctx.fillText('run = 1', (px0 + px1) / 2, Math.max(py0, py1) + 3);
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      ctx.fillText('rise = ' + rise, px2 + 4, (py1 + py2) / 2);
      // intercept dot
      ctx.fillStyle = '#c0392b';
      ctx.beginPath(); ctx.arc(px0, py0, Math.max(3, fs * 0.35), 0, 7); ctx.fill();
      // equation label
      ctx.fillStyle = L.color; ctx.font = 'bold ' + fs + 'px sans-serif';
      ctx.textAlign = 'left';
      var eq = 'y = ' + L.m + 'x ' + (L.b >= 0 ? '+ ' + L.b : '− ' + (-L.b));
