function makeChart() {
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  document.getElementById('container').appendChild(canvas);
  var ds = LINES.map(function (L) {
    return {
      label: L.name,
      data: [{ x: L.seg[0], y: L.m * L.seg[0] + L.b }, { x: L.seg[1], y: L.m * L.seg[1] + L.b }],
      borderColor: L.color, borderWidth: 2.5, pointRadius: 0, showLine: true, type: 'line'
