    label: 'candidate', data: [], borderColor: '#7b2fbf', borderWidth: 2,
    borderDash: [6, 4], pointRadius: 0, showLine: true, type: 'line'
  });
  chart = new Chart(canvas.getContext('2d'), {
    data: { datasets: ds },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      events: ['click'],
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: {
          type: 'linear', min: -7.3, max: 7.3,
          grid: { color: function (t) { return t.tick.value === 0 ? '#555' : '#ddd'; }, lineWidth: function (t) { return t.tick.value === 0 ? 1.5 : 1; } },
          ticks: { stepSize: 1, font: { size: 10 }, color: '#444' }
        },
        y: {
          min: -5.4, max: 5.4,
          grid: { color: function (t) { return t.tick.value === 0 ? '#555' : '#ddd'; }, lineWidth: function (t) { return t.tick.value === 0 ? 1.5 : 1; } },
          ticks: { stepSize: 1, font: { size: 10 }, color: '#444' }
        }
      },
      onClick: function (e) {
        var rect = chart.canvas.getBoundingClientRect();
        var x = chart.scales.x.getValueForPixel(e.x - rect.left + (e.offsetX !== undefined ? 0 : 0));
        // use offsetX/offsetY
        x = chart.scales.x.getValueForPixel(e.offsetX !== undefined ? e.offsetX : e.x - rect.left);
        var y = chart.scales.y.getValueForPixel(e.offsetY !== undefined ? e.offsetY : e.y - rect.top);
        var best = -1, bestD = 1e9;
        LINES.forEach(function (L, i) {
          if (x < L.seg[0] - 0.4 || x > L.seg[1] + 0.4) return;
          var d = Math.abs(y - (L.m * x + L.b)) / Math.sqrt(1 + L.m * L.m);
          if (d < bestD) { bestD = d; best = i; }
        });
        if (best >= 0 && bestD < 0.45) {
          selLine = best;
          var L = LINES[best];
          chart.update();
          showPopup('Line ' + L.name, 'This line crosses the y-axis at b = ' + L.b +
            ' and has slope m = ' + L.m + ' (' + (L.m >= 0 ? 'rising' : 'falling') +
            ' left to right). Its equation is y = ' + L.m + 'x ' + (L.b >= 0 ? '+ ' + L.b : '− ' + (-L.b)) +
            '. Try setting the sliders to these values — the dashed candidate line will lie exactly on top of it.');
        } else {
          selLine = -1; chart.update(); hidePopup();
        }
      },
      onHover: function (e) {
        if (!e || e.offsetX === undefined) return;
        var x = chart.scales.x.getValueForPixel(e.offsetX);
        var y = chart.scales.y.getValueForPixel(e.offsetY);
        var best = null, bestD = 1e9;
        LINES.forEach(function (L) {
          if (x < L.seg[0] - 0.4 || x > L.seg[1] + 0.4) return;
          var d = Math.abs(y - (L.m * x + L.b)) / Math.sqrt(1 + L.m * L.m);
