<!-- @FIGURE_UI_BEGIN -->
<label>Slope m: <output id="slopeSliderVal">1</output><input id="slopeSliderInput" type="range" min="-4" max="4" step="0.25" value="1" oninput="document.getElementById('slopeSliderVal').value=this.value;update_slopeSlider(+this.value)"></label>
<label>y-intercept b: <output id="interceptSliderVal">1</output><input id="interceptSliderInput" type="range" min="-5" max="5" step="0.5" value="1" oninput="document.getElementById('interceptSliderVal').value=this.value;update_interceptSlider(+this.value)"></label>
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"></p>
<div style="display:flex;gap:4px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var LINES = [
  { name: 'I', m: 3, b: 2, color: '#e87722', seg: [-2.33, 1.0] },
  { name: 'II', m: 0.5, b: 3, color: '#4a9fd8', seg: [-7, 4] },
  { name: 'III', m: 2, b: -3, color: '#1a9e8f', seg: [-1, 4] },
  { name: 'IV', m: -2, b: 3, color: '#1f3a93', seg: [-1, 4] }
];
var selM = 1, selB = 1, selLine = -1, candVisible = false;
var chart;

function candPts(m, b) {
  var xs = [];
  [[-7, m * -7 + b], [7, m * 7 + b]].forEach(function (p) { if (p[1] >= -5 && p[1] <= 5) xs.push(p); });
  if (m !== 0) {
    [5, -5].forEach(function (y) {
      var x = (y - b) / m;
      if (x >= -7 && x <= 7) xs.push([x, y]);
    });
  }
  xs.sort(function (a, c) { return a[0] - c[0]; });
  return xs.length >= 2 ? [xs[0], xs[xs.length - 1]] : [];
}

var annotationPlugin = {
  id: 'annot',
  afterDraw: function (c) {
    var ctx = c.ctx, a = c.chartArea;
    function X(x) { return c.scales.x.getPixelForValue(x); }
    function Y(y) { return c.scales.y.getPixelForValue(y); }
    var s = Math.min(a.right - a.left, a.bottom - a.top);
    var fs = Math.max(9, s * 0.028);

    function arrowhead(x1, y1, x2, y2, color) {
      var ang = Math.atan2(y2 - y1, x2 - x1), L = fs * 0.9;
      ctx.strokeStyle = color; ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(x2, y2);
      ctx.lineTo(x2 - L * Math.cos(ang - 0.4), y2 - L * Math.sin(ang - 0.4));
      ctx.lineTo(x2 - L * Math.cos(ang + 0.4), y2 - L * Math.sin(ang + 0.4));
      ctx.closePath(); ctx.fill();
    }

    // axis arrowheads
    arrowhead(X(6.4), Y(0), X(7.15), Y(0), '#333');
    arrowhead(X(0), Y(-4.6), X(0), Y(5.35), '#333');

    // line arrowheads + labels
    LINES.forEach(function (L) {
      var p1 = [X(L.seg[0]), Y(L.m * L.seg[0] + L.b)];
      var p2 = [X(L.seg[1]), Y(L.m * L.seg[1] + L.b)];
      arrowhead(p2[0], p2[1], p1[0], p1[1], L.color);
      arrowhead(p1[0], p1[1], p2[0], p2[1], L.color);
      ctx.font = 'italic bold ' + fs + 'px sans-serif';
      ctx.fillStyle = L.color;
      ctx.textBaseline = 'middle';
      var labelPt, align = 'left';
      if (L.name === 'IV') labelPt = [p2[0] + fs * 0.4, p2[1] - fs * 0.9];
      else if (L.name === 'I') labelPt = [p2[0] + fs * 0.4, p2[1] + fs * 0.6];
      else if (L.name === 'II') { labelPt = [p2[0] - fs * 0.1, p2[1] - fs * 1.4]; }
      else { labelPt = [p2[0] + fs * 0.5, p2[1] + fs * 1.4]; } // III below-right of II
      ctx.textAlign = align;
      ctx.fillText(L.name, labelPt[0], labelPt[1]);
    });

    // axis labels
    ctx.fillStyle = '#333'; ctx.font = 'italic ' + fs + 'px serif';
    ctx.textAlign = 'center';
    ctx.fillText('x', X(7.0), Y(0) + fs * 1.2);
    ctx.fillText('y', X(0) - fs * 1.1, Y(5.1));

    // candidate intercept pivot dot (only when candidate is shown)
    if (candVisible) {
      ctx.fillStyle = '#7b2fbf';
      ctx.beginPath(); ctx.arc(X(0), Y(selB), Math.max(3, fs * 0.35), 0, 7); ctx.fill();
    }

    // rise/run triangle for selected line
    if (selLine >= 0) {
      var L = LINES[selLine];
      var run = 1, rise = L.m;
      var x0 = 0, y0 = L.b;
      var px0 = X(x0), py0 = Y(y0), px1 = X(x0 + run), py1 = Y(y0), px2 = X(x0 + run), py2 = Y(y0 + rise);
      ctx.strokeStyle = '#c0392b'; ctx.lineWidth = Math.max(1, fs * 0.12);
      ctx.setLineDash([]);
      ctx.beginPath(); ctx.moveTo(px0, py0); ctx.lineTo(px1, py1); ctx.lineTo(px2, py2); ctx.stroke();
      ctx.fillStyle = '#c0392b'; ctx.font = fs * 0.85 + 'px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      ctx.fillText('run = 1', (px0 + px1) / 2, Math.max(py0, py1) + 3);
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      ctx.fillText('rise = ' + rise, px2 + 4, (py1 + py2) / 2);
      ctx.fillStyle = '#c0392b';
      ctx.beginPath(); ctx.arc(px0, py0, Math.max(3, fs * 0.35), 0, 7); ctx.fill();
      ctx.fillStyle = L.color; ctx.font = 'bold ' + fs + 'px sans-serif';
      ctx.textAlign = 'left';
      var eq = 'y = ' + L.m + 'x ' + (L.b >= 0 ? '+ ' + L.b : '− ' + (-L.b));
      var ex = Math.min(X(4.6), a.right - ctx.measureText(eq).width - 4);
      ctx.fillText(eq, ex, a.top + fs * (selLine === 3 ? 2.2 : 1.0));
    }
  }
};

function makeChart() {
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  document.getElementById('container').appendChild(canvas);
  var ds = LINES.map(function (L) {
    return {
      label: L.name,
      data: [{ x: L.seg[0], y: L.m * L.seg[0] + L.b }, { x: L.seg[1], y: L.m * L.seg[1] + L.b }],
      borderColor: L.color, borderWidth: 2.5, pointRadius: 0, showLine: true, type: 'line'
    };
  });
  ds.push({
    label: 'candidate', data: [], borderColor: '#7b2fbf', borderWidth: 2,
    borderDash: [6, 4], pointRadius: 0, showLine: true, type: 'line'
  });
  chart = new Chart(canvas.getContext('2d'), {
    data: { datasets: ds },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      events: ['click', 'mousemove'],
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: {
          type: 'linear', min: -7, max: 7,
          grid: { color: function (t) { return t.tick.value === 0 ? '#555' : '#ddd'; }, lineWidth: function (t) { return t.tick.value === 0 ? 1.5 : 1; } },
          ticks: {
            stepSize: 1, font: { size: 10 }, color: '#444',
            callback: function (v) { return (Math.abs(v) === 7) ? '' : v; }
          }
        },
        y: {
          min: -5, max: 5,
          grid: { color: function (t) { return t.tick.value === 0 ? '#555' : '#ddd'; }, lineWidth: function (t) { return t.tick.value === 0 ? 1.5 : 1; } },
          ticks: {
            stepSize: 1, font: { size: 10 }, color: '#444',
            callback: function (v) { return (Math.abs(v) === 5) ? '' : v; }
          }
        }
      },
      onClick: function (e) {
        if (e.offsetX === undefined) return;
        var x = chart.scales.x.getValueForPixel(e.offsetX);
        var y = chart.scales.y.getValueForPixel(e.offsetY);
        var best = -1, bestD = 1e9;
        LINES.forEach(function (L, i) {
          if (x < L.seg[0] - 0.4 || x > L.seg[1] + 0.4) return;
          var d = Math.abs(y - (L.m * x + L.b)) / Math.sqrt(1 + L.m * L.m);
          if (d < bestD) { bestD = d; best = i; }
        });
        if (best >= 0 && bestD < 0.45) {
          selLine = best;
          var L = LINES[best];
          chart.update();
          showPopup('Line ' + L.name, 'This line crosses the y-axis at b = ' + L.b +
            ' and has slope m = ' + L.m + ' (' + (L.m >= 0 ? 'rising' : 'falling') +
            ' left to right). Its equation is y = ' + L.m + 'x ' + (L.b >= 0 ? '+ ' + L.b : '− ' + (-L.b)) +
            '. Try setting the sliders to these values — the dashed candidate line will lie exactly on top of it.');
        } else {
          selLine = -1; chart.update(); hidePopup();
        }
      },
      onHover: function (e) {
        if (!e || e.offsetX === undefined) return;
        var x = chart.scales.x.getValueForPixel(e.offsetX);
        var y = chart.scales.y.getValueForPixel(e.offsetY);
        var best = null, bestD = 1e9;
        LINES.forEach(function (L) {
          if (x < L.seg[0] - 0.4 || x > L.seg[1] + 0.4) return;
          var d = Math.abs(y - (L.m * x + L.b)) / Math.sqrt(1 + L.m * L.m);
          if (d < bestD) { bestD = d; best = L; }
        });
        if (best && bestD < 0.45) {
          showTooltip('Line ' + best.name + ': y = ' + best.m + 'x ' + (best.b >= 0 ? '+ ' + best.b : '− ' + (-best.b)) + ' — click to inspect', e);
          chart.canvas.style.cursor = 'pointer';
        } else { hideTooltip(); chart.canvas.style.cursor = 'default'; }
      }
    },
    plugins: [annotationPlugin]
  });
  window.__markRendered();
  refreshCandidate();
}

function refreshCandidate() {
  var pts = candVisible ? candPts(selM, selB).map(function (p) { return { x: p[0], y: p[1] }; }) : [];
  chart.data.datasets[4].data = pts;
  chart.update();
}

function update_slopeSlider(v) { selM = v; candVisible = true; refreshCandidate(); }
function update_interceptSlider(v) { selB = v; candVisible = true; refreshCandidate(); }

/* step player */
var steps = [
  { title: 'Read the four lines', m: 1, b: 1, sel: -1, showCand: false },
  { title: 'Inspect a line', m: 0.5, b: 3, sel: 1, showCand: true },
  { title: 'Match slope by rotating', m: -2, b: 3, sel: 3, showCand: true },
  { title: 'Match intercept by sliding', m: 2, b: -3, sel: 2, showCand: true }
];
var narrations = [
  'Four lines share the plane: I, II, and III rise left to right (positive slope) while IV falls (negative slope). Line II is the shallowest, line I the steepest. Click any line to inspect it, or touch a slider to summon a dashed candidate line.',
  'Click line II: a rise-over-run triangle appears showing about 1 unit up for every 2 units right, and its y-intercept dot sits at 3 — so its equation must look like y = 0.5x + 3. The dashed candidate now matches it exactly.',
  'Drag the slope slider and watch the candidate line pivot about its intercept: negative values tilt it down like line IV, and steepening it brings it toward lines III and then I.',
  'Lines II and IV both cross the y-axis at 3, but line III crosses at −3. Slide b down to −3: the candidate shifts parallel to itself, showing b moves a line without changing its slope.'
];
var curStep = 0;
function goStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[curStep];
  document.getElementById('slopeSliderInput').value = st.m;
  document.getElementById('slopeSliderVal').value = st.m;
  document.getElementById('interceptSliderInput').value = st.b;
  document.getElementById('interceptSliderVal').value = st.b;
  selM = st.m; selB = st.b; selLine = st.sel; candVisible = st.showCand;
  refreshCandidate();
  document.getElementById('demoNarration').textContent = narrations[curStep];
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length + ' ' + st.title;
  hidePopup();
}
function nextStep() { goStep(curStep + 1); }
function prevStep() { goStep(curStep - 1); }

makeChart();
goStep(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

